**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("macierz.txt");
    int m[6][6];
    for (int i = 0; i < 6; i++)
        for (int j = 0; j < 6; j++)
            plik >> m[i][j];

    int sumG = 0, sumP = 0, cnt = 0;
    for (int i = 0; i < 6; i++) {
        sumG += m[i][i];
        sumP += m[i][5 - i];
        if (m[i][i] > m[i][5 - i]) cnt++;
    }

    cout << "a) Suma glownej przekatnej: " << sumG << endl;
    cout << "b) Suma przeciwnej przekatnej: " << sumP << endl;
    cout << "c) Glowna > przeciwna: " << cnt << endl;
    return 0;
}
```

**Wyjasnienie**: Glowna przekatna to elementy m[i][i], przeciwna to m[i][n-1-i]. Jedna petla wystarczy do obu operacji.

Weryfikacja:
- Glowna: m[0][0]=5, m[1][1]=7, m[2][2]=9, m[3][3]=3, m[4][4]=6, m[5][5]=2 -> 5+7+9+3+6+2=32
- Przeciwna: m[0][5]=8, m[1][4]=3, m[2][3]=6, m[3][2]=4, m[4][1]=5, m[5][0]=3 -> 8+3+6+4+5+3=29
- Porownania (glowna > przeciwna): i=0: 5>8? NIE, i=1: 7>3? TAK, i=2: 9>6? TAK, i=3: 3>4? NIE, i=4: 6>5? TAK, i=5: 2>3? NIE -> cnt=3
